            [
                'category' => 'Тестирование',
                'question' => 'Queue::fake() и Bus::fake() — как тестировать очереди и джобы в Laravel?',
                'answer' => "Когда контроллер делает `dispatch(SendEmailJob::class)`, **реально** джоб уйдёт в очередь и потом будет выполнен воркером. В тесте это не нужно — нужно проверить **факт диспатча**, а не выполнить работу.\n\n**Что подменять**:\n\n- **`Queue::fake()`** — подменяет фасад `Queue`. Перехватывает любые `Job::dispatch()` / `dispatch()`-хелперы. Самый частый вариант.\n- **`Bus::fake()`** — подменяет шину команд. Нужен, если используешь `Bus::dispatch()` / `Bus::batch()` / `Bus::chain()`.\n\n**Что можно проверить после действия**:\n\n- **`Queue::assertPushed(Job::class)`** — диспатч был.\n- **`Queue::assertPushed(Job::class, fn (\$job) => \$job->userId === \$user->id)`** — диспатч с конкретными аргументами.\n- **`Queue::assertPushedOn('emails', Job::class)`** — в конкретную очередь.\n- **`Queue::assertNotPushed(Job::class)`** — наоборот, **не** диспатчилось.\n- **`Queue::assertPushedTimes(Job::class, 3)`** — ровно `3` раза.\n- **`Bus::assertBatched(fn (\$batch) => \$batch->jobs->count() === 5)`** — батч из 5 джобов.\n- **`Bus::assertChained([JobA::class, JobB::class])`** — цепочка джобов в правильном порядке.\n\n**Подводный камень**: после `Queue::fake()` джобы **не выполняются**. Если тест проверяет результат работы джоба (запись в БД), нужно либо запустить `handle()` руками, либо тестировать сам класс джоба отдельным unit-тестом.",
                'code_example' => "<?php\n\nuse Illuminate\\Support\\Facades\\Bus;\nuse Illuminate\\Support\\Facades\\Queue;\n\npublic function test_registration_dispatches_welcome_email_job(): void\n{\n    Queue::fake();\n\n    \$this->post('/register', [\n        'email' => 'jane@example.com',\n        'password' => 'secret123',\n        'password_confirmation' => 'secret123',\n    ]);\n\n    Queue::assertPushed(SendWelcomeEmail::class, function (\$job) {\n        return \$job->email === 'jane@example.com';\n    });\n    Queue::assertPushedTimes(SendWelcomeEmail::class, 1);\n    Queue::assertNotPushed(SendPasswordResetEmail::class);\n}\n\npublic function test_import_dispatches_job_batch(): void\n{\n    Bus::fake();\n\n    (new CsvImportService())->run(storage_path('imports/users.csv'));\n\n    Bus::assertBatched(function (\\Illuminate\\Bus\\PendingBatch \$batch) {\n        return \$batch->jobs->count() === 100 && \$batch->name === 'users-import';\n    });\n}\n\npublic function test_job_handle_logic_separately(): void\n{\n    // Сам джоб тестируем как обычный класс — без Queue::fake\n    \$user = User::factory()->create();\n    (new SendWelcomeEmail(\$user->email))->handle(app(Mailer::class));\n\n    // ... assertion-ы на результат работы\n}",
                'code_language' => 'php',
                'difficulty' => 2,
                'topic' => 'testing.tools',
            ],
            [
                'category' => 'Тестирование',
                'question' => 'Event::fake() — как тестировать события в Laravel?',
                'answer' => "**`Event::fake()`** перехватывает все `event()` / `Event::dispatch()` в тесте. Слушатели **не выполняются** — мы проверяем только сам факт диспатча события.\n\n**Что проверить после действия**:\n\n- **`Event::assertDispatched(UserRegistered::class)`** — событие было.\n- **`Event::assertDispatched(UserRegistered::class, fn (\$e) => \$e->user->id === \$id)`** — с конкретными данными.\n- **`Event::assertDispatchedTimes(Event::class, 2)`** — ровно `2` раза.\n- **`Event::assertNotDispatched(UserBanned::class)`** — событие **не** уходило.\n- **`Event::assertListening(Event::class, Listener::class)`** — что слушатель **подписан** (статичная проверка регистрации).\n\n**Частичный фейк** — фейкаем не все события, а только указанные:\n\n- **`Event::fake([UserRegistered::class])`** — `UserRegistered` ловим, остальные события работают как обычно.\n- **`Event::fakeExcept([Important::class])`** — фейкаем всё **кроме** `Important`.\n- **`Event::fakeFor(fn () => ..., [Event::class])`** — фейк только на время вызова callback-а.\n\n**Когда использовать**:\n\n- Тестируем, что **контроллер** диспатчит событие → `Event::fake()` + `assertDispatched`.\n- Тестируем, что **слушатель** правильно реагирует на событие → **НЕ** фейкаем `Event::fake()`, а инстанциируем listener и зовём `handle(\$event)` напрямую.\n\n**Антипаттерн**: `Event::fake()` + ожидание, что слушатель выполнит работу. Не выполнит — он замокан.",
                'code_example' => "<?php\n\nuse Illuminate\\Support\\Facades\\Event;\n\npublic function test_registration_dispatches_user_registered_event(): void\n{\n    Event::fake([UserRegistered::class]); // только это событие фейкаем\n\n    \$response = \$this->post('/register', [\n        'email' => 'jane@example.com',\n        'password' => 'secret123',\n        'password_confirmation' => 'secret123',\n    ]);\n\n    Event::assertDispatched(UserRegistered::class, function (\$event) {\n        return \$event->user->email === 'jane@example.com';\n    });\n    Event::assertDispatchedTimes(UserRegistered::class, 1);\n}\n\npublic function test_listener_sends_welcome_mail_separately(): void\n{\n    // Слушатель тестируем БЕЗ Event::fake — звоним руками\n    \\Illuminate\\Support\\Facades\\Mail::fake();\n\n    \$listener = app(SendWelcomeMail::class);\n    \$listener->handle(new UserRegistered(User::factory()->create([\n        'email' => 'jane@example.com',\n    ])));\n\n    \\Illuminate\\Support\\Facades\\Mail::assertSent(WelcomeMail::class);\n}",
                'code_language' => 'php',
                'difficulty' => 2,
                'topic' => 'testing.tools',
            ],
            [
                'category' => 'Тестирование',
                'question' => 'Mail::fake() и Notification::fake() — как тестировать рассылки в Laravel?',
                'answer' => "Обе подменяют реальный отправщик, чтобы **не слать письма** из тестов, но позволяют проверить факт отправки.\n\n**`Mail::fake()`** — для классов **`Mailable`** (`SendOrderConfirmation extends Mailable`), которые отправляются через **`Mail::to(\$user)->send(new Mailable(...))`**.\n\n- **`Mail::assertSent(Mailable::class)`** — письмо отправлено.\n- **`Mail::assertSent(Mailable::class, fn (\$mail) => \$mail->hasTo('jane@example.com'))`** — конкретному адресату.\n- **`Mail::assertQueued(Mailable::class)`** — отправлено через очередь (`Mail::to(\$u)->queue(...)`).\n- **`Mail::assertNotSent(Mailable::class)`** / **`assertNothingSent()`**.\n\n**`Notification::fake()`** — для классов **`Notification`**, отправляемых через **`\$user->notify(new Notification(...))`** или **`Notification::send(\$users, ...)`**. Уведомления могут идти **разными каналами** — `mail`, `sms`, `slack`, `database`.\n\n- **`Notification::assertSentTo(\$user, Welcome::class)`** — конкретному юзеру.\n- **`Notification::assertSentTo(\$user, Welcome::class, fn (\$n, \$channels) => in_array('mail', \$channels))`** — конкретным каналом.\n- **`Notification::assertSentToTimes(\$user, Welcome::class, 1)`** — ровно `1` раз.\n- **`Notification::assertNothingSent()`**.\n\n**Когда что выбрать**:\n\n- Одноразовое письмо без каналов → **`Mailable`** + **`Mail::fake()`**.\n- Логика «есть несколько каналов доставки» (email + push + Slack) → **`Notification`** + **`Notification::fake()`**.\n- Когда `Notification` отправляет через mail-канал — **`Mail::fake()`** не сработает, нужен **`Notification::fake()`**.",
                'code_example' => "<?php\n\nuse Illuminate\\Support\\Facades\\Mail;\nuse Illuminate\\Support\\Facades\\Notification;\n\npublic function test_order_confirmation_email_is_sent(): void\n{\n    Mail::fake();\n\n    \$user = User::factory()->create(['email' => 'jane@example.com']);\n    \$this->actingAs(\$user)->post('/orders', ['product_id' => 1]);\n\n    Mail::assertSent(OrderConfirmationMail::class, function (OrderConfirmationMail \$mail) use (\$user) {\n        return \$mail->hasTo(\$user->email);\n    });\n    Mail::assertSentCount(1);\n}\n\npublic function test_password_reset_sends_notification_via_mail_channel(): void\n{\n    Notification::fake();\n\n    \$user = User::factory()->create();\n    \$this->post('/forgot-password', ['email' => \$user->email]);\n\n    Notification::assertSentTo(\n        \$user,\n        ResetPasswordNotification::class,\n        function (\$notification, array \$channels) {\n            return in_array('mail', \$channels);\n        }\n    );\n}\n\npublic function test_no_emails_on_invalid_payload(): void\n{\n    Mail::fake();\n    Notification::fake();\n\n    \$this->post('/orders', ['product_id' => 0]); // невалидный\n\n    Mail::assertNothingSent();\n    Notification::assertNothingSent();\n}",
                'code_language' => 'php',
                'difficulty' => 2,
                'topic' => 'testing.tools',
            ],
            [
                'category' => 'Тестирование',
                'question' => 'Что такое Infection и как запускать mutation testing в PHP?',
                'answer' => "**`Infection`** — инструмент mutation testing для PHP. Установка через composer как dev-зависимость, понимает `PHPUnit` и `Pest` из коробки.\n\n**Как работает**:\n\n1. Парсит исходники, ищет места под мутацию: `>`, `<`, `==`, `+`, `-`, `if`, `return`.\n2. **Применяет мутацию** — переписывает `.php` в памяти (исходник не трогает).\n3. **Гоняет твои тесты** на каждом мутанте.\n4. Считает **MSI** — % убитых мутантов.\n\n**Базовый запуск**:\n\n- **`vendor/bin/infection`** — прогон с настройками по умолчанию.\n- **`--threads=4`** — параллельные процессы.\n- **`--min-msi=80`** — упасть, если MSI ниже 80%. Это в CI ставят как **порог качества тестов**.\n- **`--filter=app/Services/`** — гонять мутации только в указанной папке (полезно для legacy-кода, где не везде хочется идеальный MSI).\n\n**Конфиг `infection.json5`** в корне проекта:\n\n- `source.directories` — где искать код.\n- `mutators` — какие мутации применять (`@default`, `@arithmetic`, можно отключать неудобные).\n- `logs.html` — путь для HTML-отчёта со списком выживших мутантов.\n\n**Где смотреть результаты**: HTML-отчёт показывает каждого выжившего мутанта — какая строка, какая мутация, какие тесты её прогнали и не упали. По этому списку **дописываешь тесты**.\n\n**Минусы**:\n\n- Очень медленно — `N тестов × M мутантов`. Полный прогон на большом проекте — десятки минут.\n- В CI запускают **ночью** или **только на изменённых файлах** через `--git-diff-filter=A`.",
                'code_example' => "// composer.json — установка\n{\n    \"require-dev\": {\n        \"infection/infection\": \"^0.27\"\n    }\n}\n\n// infection.json5 в корне\n{\n    \"\$schema\": \"vendor/infection/infection/resources/schema.json\",\n    \"source\": {\n        \"directories\": [\"app\"]\n    },\n    \"timeout\": 10,\n    \"logs\": {\n        \"text\": \"infection.log\",\n        \"html\": \"reports/infection.html\"\n    },\n    \"mutators\": {\n        \"@default\": true\n    }\n}\n\n# Запуск\nvendor/bin/infection --threads=4 --min-msi=80\n\n# Только изменённые в PR файлы\nvendor/bin/infection --git-diff-filter=A --git-diff-base=origin/main\n\n# Пример выхода\n#  9 mutations were generated:\n#     8 mutants were killed\n#     1 mutants were not covered by tests\n#  Metrics:\n#     Mutation Score Indicator (MSI): 88%\n#     Covered Code MSI: 100%",
                'code_language' => 'json',
                'difficulty' => 3,
                'topic' => 'testing.tools',
            ],
        ];
    }
